tool_calls.arguments:
{"command":"cd /workspace && kubectl apply -f <<'EOF'
apiVersion: apps/v1
kind: Deployment
metadata: {name: verify, namespace: default}
spec: {replicas: 1, selector: {matchLabels: {app: verify}}, template: {metadata: {labels: {app: verify}}, spec: {containers: [{image: registry:3.1.1,name: v,dryRun:false}]}}, imagePullPolicy: IfNotPresent}}
EOF
sleep 20; kubectl get deploy verify -o wide; kubectl logs -n default deploy/verify --tail=40 2>&1 | head; echo ---; kubectl get pods -A"}

{"command":"cd /workspace && cat > /tmp/app.yaml <<'EOF'
apiVersion: apps/v1
kind: Deployment
metadata: {name: app, namespace: default}
spec: {replicas: 3, selector: {matchLabels: {app: app}}, template: {metadata: {labels: {app: app}}, spec: {containers: [{image: registry:5000/private/hello:1.0,name: app,imagePullPolicy: Always}]}}}}
EOF
kubectl apply -f /tmp/app.yaml; sleep 90; kubectl get deploy app; kubectl get pods -o wide"}

